package dev.matchlab;
import java.io.*; import java.nio.file.*; import java.util.*;
public final class TelemetryAnalyzer {
 public record Sample(long ms,double x,double y,double targetX,double targetY,double leftPower,double rightPower,int cycle,boolean autoComplete){}
 public record Fault(String rule,String explanation,double value){}
 public record Report(int samples,double rmsPathError,double cycleStdDev,double motorImbalance,double reliability,List<Fault> faults){}
 public List<Sample> parse(Path path)throws IOException{var out=new ArrayList<Sample>();int lineNo=1;for(var line:Files.readAllLines(path)){lineNo++;if(line.isBlank()||line.startsWith("time_ms"))continue;var c=line.split(",",-1);if(c.length!=9)throw new IllegalArgumentException("line "+lineNo+" requires 9 columns");try{out.add(new Sample(Long.parseLong(c[0]),Double.parseDouble(c[1]),Double.parseDouble(c[2]),Double.parseDouble(c[3]),Double.parseDouble(c[4]),Double.parseDouble(c[5]),Double.parseDouble(c[6]),Integer.parseInt(c[7]),Boolean.parseBoolean(c[8])));}catch(NumberFormatException e){throw new IllegalArgumentException("invalid number on line "+lineNo,e);}}if(out.isEmpty())throw new IllegalArgumentException("no telemetry samples");return out;}
 public Report analyze(List<Sample> s){double sq=s.stream().mapToDouble(v->Math.pow(Math.hypot(v.x-v.targetX,v.y-v.targetY),2)).average().orElse(0);double imbalance=s.stream().mapToDouble(v->Math.abs(v.leftPower-v.rightPower)).average().orElse(0);var byCycle=new TreeMap<Integer,Long>();for(var v:s)byCycle.merge(v.cycle,1L,Long::sum);double avg=byCycle.values().stream().mapToLong(x->x).average().orElse(0);double variance=byCycle.values().stream().mapToDouble(x->Math.pow(x-avg,2)).average().orElse(0);long cycles=s.stream().map(Sample::cycle).distinct().count(),ok=s.stream().filter(Sample::autoComplete).map(Sample::cycle).distinct().count();double reliability=cycles==0?0:(double)ok/cycles;var f=new ArrayList<Fault>();double rms=Math.sqrt(sq);if(rms>0.30)f.add(new Fault("path-error","RMS path error exceeds 0.30 m",rms));if(imbalance>0.20)f.add(new Fault("motor-imbalance","Average left/right command difference exceeds 0.20",imbalance));if(reliability<0.9)f.add(new Fault("auto-reliability","Fewer than 90% of cycles completed",reliability));return new Report(s.size(),rms,Math.sqrt(variance),imbalance,reliability,List.copyOf(f));}
}
